// spec: specs/delivery.md §4 · кейс .qa/tests/delivery/dlv-06-print-no-delivered-at.md
// seed: tests/seed.admin.spec.ts
// #539c2f (עבר QA 21.10; решение пользователя 20.10 — «סופק ב» убрать только из печати/PDF, на экране оставить):
// печатная תעודת משלוח (emulateMedia print) заказа «סופק» — нет «סופק ב…» и «סטטוס»; есть «שעת הזמנה» и «שעת יעד לאספקה» (#599f82).
// Данные: заказ #542 (test, סופק 18.10, שעת יעד «עד 17:30») — только чтение, печать браузера не вызывается.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const ORDER = '542';

async function openDeliveredNote(page: Page) {
  await page.goto('/delivery');
  await expect(page.getByRole('heading', { level: 1, name: 'משלוחים' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('button', { name: 'הצגת משלוחים שסופקו' }).click();
  const link = page.getByRole('link', { name: `תעודת משלוח · הזמנה #${ORDER}`, exact: true });
  await expect(page.getByRole('heading', { level: 2, name: 'סופקו' })).toBeVisible({ timeout: 30_000 });
  test.skip(!(await link.count()), `заказ #${ORDER} не найден среди «סופקו»`);
  await link.click();
  await expect(page.getByRole('heading', { level: 1, name: `תעודת משלוח · הזמנה #${ORDER}` })).toBeVisible({ timeout: 30_000 });
  await expect(page.getByText(`ת. משלוח #DN-${ORDER}`)).toBeVisible();
}

test.describe('delivery — תעודת משלוח מודפסת בלי «סופק ב» (#539c2f)', () => {
  test('מסך: «סופק ב-…» נשאר; הדפסה: אין «סופק ב»/«סטטוס», יש «שעת הזמנה» ו«שעת יעד לאספקה» #539c2f @desktop @prod-safe', async ({ page }) => {
    await openDeliveredNote(page);
    // экран תעודה — отметка времени поставки остаётся (решение 20.10)
    await expect(page.getByText(/^סופקה ב-?\s*\d{2}\.\d{2}\.\d{4}, \d{2}:\d{2}$/)).toBeVisible();

    await page.emulateMedia({ media: 'print' });
    await expect(page.getByText('פריטי המשלוח')).toBeVisible();
    await expect(page.getByText(/^הופק: \d{2}\.\d{2}\.\d{4}, \d{2}:\d{2}$/)).toBeVisible();
    const printed = await page.evaluate(() => document.body.innerText);
    expect(printed, 'в печати нет «סופק ב»').not.toMatch(/סופקה? ב/);
    expect(printed, 'в печати нет «סטטוס» (#ad4f1b)').not.toMatch(/סטטוס/);
    expect(printed, 'в печати есть «שעת הזמנה»').toMatch(/שעת הזמנה:\s*\d{2}:\d{2}/);
    expect(printed, 'в печати есть «שעת יעד לאספקה»').toMatch(/שעת יעד לאספקה:/);
    expect(printed).toContain(`DN-${ORDER}`);
    // блок клиента на месте
    for (const t of ['לקוח', 'איש קשר', 'כתובת משלוח', 'טלפון']) expect(printed).toContain(t);
    await page.emulateMedia({ media: 'screen' });
  });
});
